const crypto=require('crypto'); const fail=(statusCode,error)=>[{json:{ok:false,statusCode,error}}]; const authorization=$json.headers?.authorization??''; if(!authorization.startsWith('Bearer ')) return fail(401,'Sesión requerida.'); const secret=$env.JWT_SECRET; if(!secret) return fail(500,'JWT_SECRET no está configurado.');
try {
 const token=authorization.slice(7).trim(); const [h,p,s,x]=token.split('.'); if(!h||!p||!s||x) throw new Error(); const expected=crypto.createHmac('sha256',secret).update(`${h}.${p}`).digest('base64url'); const left=Buffer.from(s),right=Buffer.from(expected); if(left.length!==right.length||!crypto.timingSafeEqual(left,right)) throw new Error(); const payload=JSON.parse(Buffer.from(p,'base64url').toString('utf8')); if(!payload.exp||payload.exp<=Math.floor(Date.now()/1000)) throw new Error(); const role=String(payload.rol??payload.role??'').toUpperCase(); const permissions=(Array.isArray(payload.permisos)?payload.permisos:[]).map(v=>String(v).toLowerCase()); if(role!=='SUPERADMIN'&&!permissions.includes('parqueadero.gestionar')) return fail(403,'No tiene permisos para gestionar parqueadero.');
 const body=$json.body??{}; const parkingUserId=Number(body.parkingUserId); const vehicleId=Number(body.vehicleId); const modality=String(body.modality??'').toUpperCase(); const startDate=String(body.startDate??''); const method=String(body.method??'').toUpperCase(); const status=String(body.status??'').toUpperCase(); const issueAuthorization=body.issueAuthorization===true && status==='APROBADO'; const reference=method==='TRANSFERENCIA'?String(body.reference??'').trim():null; const panelUserId=Number(payload.uid??payload.sub);
 if(!Number.isInteger(parkingUserId)||parkingUserId<=0||!Number.isInteger(vehicleId)||vehicleId<=0) return fail(400,'Seleccione un usuario y vehículo válidos.'); if(!['DIARIO','MENSUAL'].includes(modality)) return fail(400,'Seleccione una modalidad válida.'); if(!/^\d{4}-\d{2}-\d{2}$/.test(startDate)||Number.isNaN(Date.parse(`${startDate}T00:00:00Z`))) return fail(400,'Seleccione una fecha válida.'); if(!['EFECTIVO','TRANSFERENCIA'].includes(method)) return fail(400,'Seleccione una forma de pago válida.'); if(!['PENDIENTE','APROBADO'].includes(status)) return fail(400,'Seleccione un estado de pago válido.'); if(method==='TRANSFERENCIA'&&(!reference||reference.length>120)) return fail(400,'Ingrese una referencia de transferencia válida.'); if(!Number.isInteger(panelUserId)||panelUserId<=0) return fail(401,'La sesión no identifica al usuario del panel.');
 return [{json:{ok:true,parkingUserId,vehicleId,modality,startDate,method,reference,status,issueAuthorization,panelUserId}}];
} catch { return fail(401,'La sesión es inválida o ha vencido.'); }
